/// <reference types="vitest/config" />
import react from '@vitejs/plugin-react';
import { defineConfig } from 'vite';
import { VitePWA } from 'vite-plugin-pwa';

// Brand colours from src/index.css (--brand, --bg). The manifest cannot read CSS variables.
const BRAND = '#0E7C66';
const BACKGROUND = '#F3F6F5';

export default defineConfig({
  plugins: [
    react(),
    // Makes BillBol an installable app (PWA): a web app manifest (name, icons, colours) and a
    // service worker, generated by Workbox at build time, that keeps the app's own files on the
    // phone so it opens instantly and even without internet.
    VitePWA({
      // "prompt", not "autoUpdate": a new version waits until the shopkeeper taps "Update"
      // (see UpdateBanner). Reloading on its own could wipe a half-made bill at the counter.
      registerType: 'prompt',
      // The icons are already precached by globPatterns below; don't list them twice.
      includeManifestIcons: false,
      manifest: {
        name: 'BillBol · Voice billing for kirana stores',
        short_name: 'BillBol',
        description: 'Bolo, aur bill taiyaar. Voice and barcode billing, udhaar khata and AI insights for kirana stores.',
        lang: 'en-IN',
        // Opens straight to the shop, not the marketing page; not logged in goes to /login.
        start_url: '/dashboard',
        scope: '/',
        // No browser address bar or tabs: looks and feels like an app from the Play Store.
        display: 'standalone',
        theme_color: BRAND,
        background_color: BACKGROUND,
        categories: ['business', 'finance', 'productivity'],
        // Made from public/favicon.svg by `npm run generate-pwa-assets` (pwa-assets.config.ts).
        // "maskable" has extra brand-coloured padding for launchers that crop icons to a circle.
        icons: [
          { src: '/pwa-64x64.png', sizes: '64x64', type: 'image/png' },
          { src: '/pwa-192x192.png', sizes: '192x192', type: 'image/png' },
          { src: '/pwa-512x512.png', sizes: '512x512', type: 'image/png' },
          { src: '/maskable-icon-512x512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
        ],
        // Long-press the app icon on Android for these.
        shortcuts: [
          { name: 'New bill', short_name: 'New bill', url: '/bills/new' },
          { name: 'Udhaar khata', short_name: 'Udhaar', url: '/customers' },
          { name: 'Receive goods', short_name: 'Receive', url: '/stock/receive' },
        ],
      },
      workbox: {
        // Precache: the built app shell (every hashed JS/CSS file plus index.html and icons).
        // Hashed names mean a new deploy gets new files; old ones are cleaned up automatically.
        globPatterns: ['**/*.{js,css,html,svg,png,ico,woff2}'],
        // Any page URL (/bills/123, /customers) loads index.html from the cache, and React Router
        // takes over, exactly like the Vercel rewrite does online...
        navigateFallback: '/index.html',
        // ...but never for the API. API responses are NEVER cached: they hold live stock, money and
        // login state, and showing an old balance or a logged-out user's data would be wrong.
        navigateFallbackDenylist: [/^\/api\//],
        cleanupOutdatedCaches: true,
        runtimeCaching: [
          // Google Fonts: the stylesheet can change, so serve the cached copy and refresh it in
          // the background; the font files themselves never change, so cache them for a year.
          {
            urlPattern: /^https:\/\/fonts\.googleapis\.com\/.*/i,
            handler: 'StaleWhileRevalidate',
            options: { cacheName: 'google-fonts-css' },
          },
          {
            urlPattern: /^https:\/\/fonts\.gstatic\.com\/.*/i,
            handler: 'CacheFirst',
            options: {
              cacheName: 'google-fonts-files',
              expiration: { maxEntries: 20, maxAgeSeconds: 60 * 60 * 24 * 365 },
              cacheableResponse: { statuses: [0, 200] },
            },
          },
        ],
      },
      // No service worker during `npm run dev`: cached files there make code changes look like
      // they did not work. Test the PWA with `npm run build && npm run preview`.
      devOptions: { enabled: false },
    }),
  ],
  server: {
    port: 5173,
    // Calls to /api go to the Express server, so the frontend never hard-codes the API URL.
    proxy: {
      '/api': {
        target: 'http://localhost:4000',
        changeOrigin: true,
      },
    },
  },
  // Client unit tests (npm test): plain logic such as money, quantities and voice intents.
  // They run in Node, no browser needed.
  test: {
    environment: 'node',
    include: ['src/**/*.test.ts'],
  },
  preview: {
    // `npm run preview` serves the production build (with the service worker); it needs the
    // same /api proxy to talk to the local server.
    proxy: {
      '/api': {
        target: 'http://localhost:4000',
        changeOrigin: true,
      },
    },
  },
});
